def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]

    # Iterate through all possible starting points for the prefix
    for i in range(len(s) - len(prefix) + 1):
        if s[i:i + len(prefix)] == prefix:
            # Check if there are enough characters left in s to match the suffix
            if len(s[i + len(prefix):]) >= len(suffix):
                if s[i + len(prefix):].startswith(suffix):
                    return True
    return False

