def largestInteger(nums: List[int], k: int) -> int:
    from collections import defaultdict

    count = defaultdict(int)
    n = len(nums)

    # Count occurrences of each number in every subarray of size k
    for i in range(n - k + 1):
        unique_numbers = set()
        for j in range(i, i + k):
            unique_numbers.add(nums[j])
        for number in unique_numbers:
            count[number] += 1

    # Find the largest integer that appears in exactly one subarray
    largest_missing = -1
    for number in count:
        if count[number] == 1:
            largest_missing = max(largest_missing, number)

    return largest_missing

