def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    # dp[i][j] will store the length of the longest subsequence 
    # ending at nums[i] with the last absolute difference being j
    dp = [[1] + [0] * (n) for _ in range(n)]
    max_length = 1

    for i in range(1, n):
        for j in range(i):
            diff = abs(nums[i] - nums[j])
            if diff <= n:
                dp[i][diff] = max(dp[i][diff], dp[j][diff] + 1)
                max_length = max(max_length, dp[i][diff])

    return max_length

