def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    # dp[i][j][k] means the maximum coins we can collect when we reach (i, j) with k neutralizations used
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0]  # Starting point with 0 neutralizations used

    for i in range(m):
        for j in range(n):
            for k in range(3):  # k is the number of neutralizations used
                if i > 0:  # Coming from the top
                    if coins[i][j] >= 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + coins[i][j])
                    elif k > 0:
                        # Neutralize the robbery
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1])  # using neutralization
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] - abs(coins[i][j]))  # not using neutralization
                if j > 0:  # Coming from the left
                    if coins[i][j] >= 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + coins[i][j])
                    elif k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1])  # using neutralization
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] - abs(coins[i][j]))  # not using neutralization

    # We want the maximum coins at the bottom-right corner with any neutralization used
    return max(dp[m-1][n-1])

