def minCost(n: int, cost: List[List[int]]) -> int:
    dp = [[0] * 3 for _ in range(n)]
    dp[0] = cost[0]
    for i in range(1, n):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(dp[i-1][(j+1)%3], dp[i-1][(j+2)%3])

    half_n = n // 2
    min_cost = float('inf')

    for j in range(3):
        for k in range(3):
            if j != k:
                cost_pair = dp[half_n][j] + dp[n-1][k]
                min_cost = min(min_cost, cost_pair)

    return min_cost

